            {
                result *= 1.35;
                result += LevelTier * 4.5;
            }
            double decay = Math.Sin(inputVal * 0.05) * 2.0;
            return Math.Max(0.0, Math.Round(result + decay, 3));
        }

        public bool ValidateCondition_3(double currentThreshold, List<string> requiredTags)
